'   :P10024_FEEDBACK        := l_feedback.feedback;',
'   :P10024_RESPONSE        := l_feedback.public_response;',
'   :P10024_FEEDBACK_STATUS := l_feedback.feedback_status;',
'   :P10024_USER_AGENT      := l_feedback.http_user_agent;',
'end loop;'))
